const hosts = $json.result || [];
const hostids = hosts.map(h => h.hostid);
const now = Math.floor(Date.now() / 1000);
const timeFrom = now - 86400;
const nowStr = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    hosts,
    time_from: timeFrom,
    time_till: now,
    generated_at: nowStr,
    cpu_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 2,
      params: {
        output: ['itemid', 'hostid', 'key_'],
        hostids,
        search: { key_: 'system.cpu.util' },
        monitored: true
      }
    }),
    mem_items_body: JSON.stringify({
      jsonrpc: '2.0', method: 'item.get', id: 3,
      params: {
        output: ['itemid', 'hostid', 'key_'],
        hostids,
        search: { key_: 'vm.memory' },
        monitored: true
      }
    })
  }
}];

const prep = $('Preparar Item Queries').item.json;
const cpuItems = $('Buscar Items CPU').item.json.result || [];
const memItemsRaw = $json.result || [];

// Um item de CPU por host — prefere system.cpu.util exato
const cpuByHost = {};
for (const item of cpuItems) {
  if (!cpuByHost[item.hostid] || item.key_ === 'system.cpu.util') {
    cpuByHost[item.hostid] = item;
  }
}

// Um item de memoria por host — prefere vm.memory.utilization, fallback vm.memory.size[pused]
const memByHost = {};
for (const item of memItemsRaw) {
  const key = item.key_;
  if (key === 'vm.memory.utilization') {
    memByHost[item.hostid] = item;
  } else if (key === 'vm.memory.size[pused]' && !memByHost[item.hostid]) {
    memByHost[item.hostid] = item;
  }
}

const cpuItemids = Object.values(cpuByHost).map(i => i.itemid);
const memItemids = Object.values(memByHost).map(i => i.itemid);

return [{
  json: {
    hosts: prep.hosts,
    time_from: prep.time_from,
    time_till: prep.time_till,
    generated_at: prep.generated_at,
    cpuByHost,
    memByHost,
    cpu_trend_body: JSON.stringify({
      jsonrpc: '2.0', method: 'trend.get', id: 4,
      params: {
        output: ['itemid', 'clock', 'value_avg'],
        itemids: cpuItemids,
        time_from: prep.time_from,
        time_till: prep.time_till
      }
    }),
    mem_trend_body: JSON.stringify({
      jsonrpc: '2.0', method: 'trend.get', id: 5,
      params: {
        output: ['itemid', 'clock', 'value_avg'],
        itemids: memItemids,
        time_from: prep.time_from,
        time_till: prep.time_till
      }
    })
  }
}];

const prep = $('Preparar Trend Queries').item.json;
const cpuTrends = $('Buscar Trends CPU').item.json.result || [];
const memTrends = $json.result || [];

const CPU_THRESHOLD = 5;
const MEM_THRESHOLD = 20;

// Inverte mapa itemid -> hostid
const cpuItemToHost = {};
for (const [hostid, item] of Object.entries(prep.cpuByHost)) {
  cpuItemToHost[item.itemid] = hostid;
}
const memItemToHost = {};
for (const [hostid, item] of Object.entries(prep.memByHost)) {
  memItemToHost[item.itemid] = hostid;
}

// Media de CPU por host (ultimas 24h)
const cpuSums = {}, cpuCounts = {};
for (const t of cpuTrends) {
  const hostid = cpuItemToHost[t.itemid];
  if (!hostid) continue;
  cpuSums[hostid]  = (cpuSums[hostid]  || 0) + parseFloat(t.value_avg);
  cpuCounts[hostid] = (cpuCounts[hostid] || 0) + 1;
}

// Media de Memoria por host (ultimas 24h)
const memSums = {}, memCounts = {};
for (const t of memTrends) {
  const hostid = memItemToHost[t.itemid];
  if (!hostid) continue;
  memSums[hostid]  = (memSums[hostid]  || 0) + parseFloat(t.value_avg);
  memCounts[hostid] = (memCounts[hostid] || 0) + 1;
}

const report = [];
for (const host of prep.hosts) {
  const id = host.hostid;
  const cpu = cpuCounts[id] ? Math.round((cpuSums[id] / cpuCounts[id]) * 10) / 10 : null;
  const mem = memCounts[id] ? Math.round((memSums[id] / memCounts[id]) * 10) / 10 : null;
  const hasData = cpu !== null && mem !== null;
  const isGhost = hasData && cpu < CPU_THRESHOLD && mem < MEM_THRESHOLD;
  report.push({ host: host.name, hostname: host.host, cpu, mem, hasData, isGhost });
}

const ghosts = report.filter(r => r.isGhost);
const noData  = report.filter(r => !r.hasData);

return [{ json: {
  report, ghosts, noData,
  total: prep.hosts.length,
  CPU_THRESHOLD, MEM_THRESHOLD,
  generated_at: prep.generated_at
} }];

const { ghosts, noData, total, CPU_THRESHOLD, MEM_THRESHOLD, generated_at } = $json;

const color = ghosts.length === 0 ? '00B050' : (ghosts.length > 5 ? 'FF0000' : 'FFA500');

const sections = [{
  activityTitle: 'Relatorio de Hosts Fantasmas (media 24h) — ' + generated_at,
  activitySubtitle: ghosts.length + ' fantasma(s) de ' + total + ' hosts monitorados',
  facts: [
    { name: 'Criterio',             value: 'CPU medio < ' + CPU_THRESHOLD + '% E Memoria media < ' + MEM_THRESHOLD + '%' },
    { name: 'Total monitorado',     value: String(total) },
    { name: 'Hosts fantasmas',      value: String(ghosts.length) },
    { name: 'Sem dados de metrica', value: String(noData.length) }
  ],
  markdown: true
}];

if (ghosts.length > 0) {
  sections.push({
    activityTitle: 'Hosts com Baixissimo Uso',
    text: ghosts.map(g => '**' + g.host + '** — CPU: ' + g.cpu + '% | Mem: ' + g.mem + '%').join('\n\n'),
    markdown: true
  });
}

if (noData.length > 0) {
  sections.push({
    activityTitle: 'Sem Dados (item nao encontrado ou tendencias sem historico)',
    text: noData.map(h => h.host).join(', '),
    markdown: true
  });
}

return [{
  json: {
    teams_body: JSON.stringify({
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: color,
      summary: 'Hosts fantasmas: ' + ghosts.length + ' de ' + total,
      sections
    })
  }
}];
